CREATE TABLE public.parent_access_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, student_full_name text NOT NULL, student_id uuid REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.parent_access_requests TO authenticated;
GRANT ALL ON public.parent_access_requests TO service_role;
ALTER TABLE public.parent_access_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY parent_requests_read ON public.parent_access_requests FOR SELECT TO authenticated USING (parent_id=auth.uid() OR public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'admin'));
CREATE TRIGGER parent_request_audit AFTER INSERT OR UPDATE OR DELETE ON public.parent_access_requests FOR EACH ROW EXECUTE FUNCTION public.audit_row_change('admin');
CREATE FUNCTION public.create_parent_access_request(p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_parent text; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'parent') THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(p_name))<3 OR length(trim(p_name))>200 OR position(' ' in trim(p_name))=0 THEN RAISE EXCEPTION 'Shkruani emrin dhe mbiemrin e nxënësit'; END IF; INSERT INTO parent_access_requests(parent_id,student_full_name) VALUES(auth.uid(),trim(p_name)) RETURNING id INTO v_id; SELECT first_name||' '||last_name INTO v_parent FROM profiles WHERE id=auth.uid(); INSERT INTO notifications(user_id,title,message,type,link) SELECT DISTINCT user_id,'Kërkesë prindi',v_parent||' kërkon akses si prind i nxënësit '||trim(p_name),'parent','/parent' FROM user_roles WHERE role IN ('teacher','admin'); RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.create_parent_access_request(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_parent_access_request(text) TO authenticated;
CREATE FUNCTION public.parent_request_on_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_name text; BEGIN v_name:=trim(NEW.raw_user_meta_data->>'student_full_name'); IF NEW.raw_user_meta_data->>'role'='parent' AND coalesce(v_name,'')<>'' THEN IF length(v_name)>200 OR position(' ' in v_name)=0 THEN RAISE EXCEPTION 'Shkruani emrin dhe mbiemrin e nxënësit'; END IF; INSERT INTO parent_access_requests(parent_id,student_full_name) VALUES(NEW.id,v_name); INSERT INTO notifications(user_id,title,message,type,link) SELECT DISTINCT user_id,'Kërkesë prindi',coalesce(NEW.raw_user_meta_data->>'first_name','')||' '||coalesce(NEW.raw_user_meta_data->>'last_name','')||' kërkon akses si prind i nxënësit '||v_name,'parent','/parent' FROM user_roles WHERE role IN ('teacher','admin'); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.parent_request_on_signup() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_parent_request_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.parent_request_on_signup();
CREATE FUNCTION public.review_parent_access(p_request uuid,p_student uuid,p_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_request parent_access_requests; v_student profiles; BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO v_request FROM parent_access_requests WHERE id=p_request FOR UPDATE; IF NOT FOUND OR v_request.status<>'pending' THEN RAISE EXCEPTION 'Kërkesa nuk është në pritje'; END IF; IF p_approve THEN SELECT * INTO v_student FROM profiles WHERE id=p_student AND public.has_role(id,'student'); IF NOT FOUND OR lower(regexp_replace(trim(v_student.first_name||' '||v_student.last_name),'\s+',' ','g'))<>lower(regexp_replace(trim(v_request.student_full_name),'\s+',' ','g')) THEN RAISE EXCEPTION 'Emri i nxënësit nuk përputhet me kërkesën'; END IF; INSERT INTO parent_links(parent_id,student_id) SELECT v_request.parent_id,p_student WHERE NOT EXISTS(SELECT 1 FROM parent_links WHERE parent_id=v_request.parent_id AND student_id=p_student); END IF; UPDATE parent_access_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,student_id=CASE WHEN p_approve THEN p_student END,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=p_request; INSERT INTO notifications(user_id,title,message,type,link) VALUES(v_request.parent_id,'Kërkesa e prindit',CASE WHEN p_approve THEN 'Kërkesa u aprovua për ' ELSE 'Kërkesa u refuzua për ' END||v_request.student_full_name,'parent','/parent'); END $$;
REVOKE ALL ON FUNCTION public.review_parent_access(uuid,uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.review_parent_access(uuid,uuid,boolean) TO authenticated;
CREATE FUNCTION public.parent_academic_overview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'parent') THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'first_name',p.first_name,'last_name',p.last_name,'drejtimi',p.drejtimi,'klasa',p.klasa,'paralelja',p.paralelja,
'courses',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'status',e.status,'teacher', (SELECT first_name||' '||last_name FROM profiles WHERE id=c.teacher_id),'topics',(SELECT count(*) FROM topics WHERE course_id=c.id AND deleted_at IS NULL),'completed',(SELECT count(*) FROM topic_progress pr JOIN topics t ON t.id=pr.topic_id WHERE pr.student_id=p.id AND t.course_id=c.id AND t.deleted_at IS NULL))) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.student_id=p.id AND c.deleted_at IS NULL),'[]'::jsonb),
'grades',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'grade',coalesce(a.final_grade,a.grade),'feedback',a.teacher_feedback,'pending',a.needs_review AND NOT a.reviewed,'date',a.created_at,'course_id',t.course_id,'title',q.title)) FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id JOIN topics t ON t.id=q.topic_id WHERE a.student_id=p.id),'[]'::jsonb),
'homeworkGrades',coalesce((SELECT jsonb_agg(jsonb_build_object('course_id',g.course_id,'grade',g.grade,'feedback',g.feedback)) FROM course_homework_grades g WHERE g.student_id=p.id),'[]'::jsonb),
'homework',coalesce((SELECT jsonb_agg(jsonb_build_object('id',h.id,'instructions',h.instructions,'due_date',h.due_date,'title',t.title,'course_id',t.course_id,'submissions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'grade',s.grade,'feedback',s.feedback,'date',s.created_at)) FROM homework_submissions s WHERE s.homework_id=h.id AND s.student_id=p.id),'[]'::jsonb))) FROM homework h JOIN topics t ON t.id=h.topic_id WHERE EXISTS(SELECT 1 FROM enrollments e WHERE e.student_id=p.id AND e.course_id=t.course_id AND e.status='approved')),'[]'::jsonb),
'attendance',coalesce((SELECT jsonb_agg(jsonb_build_object('date',a.date,'status',a.status,'note',a.note,'course_id',a.course_id) ORDER BY a.date DESC) FROM attendance a WHERE a.student_id=p.id),'[]'::jsonb),
'exams',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'scheduled_at',x.scheduled_at,'duration_min',x.duration_min,'room',x.room)) FROM exams x WHERE EXISTS(SELECT 1 FROM enrollments e WHERE e.student_id=p.id AND e.course_id=x.course_id AND e.status='approved')),'[]'::jsonb),
'schedule',coalesce((SELECT jsonb_agg(jsonb_build_object('day',s.day_of_week,'start',s.start_time,'end',s.end_time,'room',s.room,'course',(SELECT title FROM courses WHERE id=s.course_id))) FROM schedule s WHERE EXISTS(SELECT 1 FROM enrollments e WHERE e.student_id=p.id AND e.course_id=s.course_id AND e.status='approved')),'[]'::jsonb))) FROM profiles p WHERE EXISTS(SELECT 1 FROM parent_links l WHERE l.parent_id=auth.uid() AND l.student_id=p.id)),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.parent_academic_overview() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.parent_academic_overview() TO authenticated;